const fs = require("fs");

// copy the react-table-config from src and put it
try {
  fs.writeFileSync("dist/index.d.ts", 'export * from "./components";');
  fs.writeFileSync("dist/typings.d.ts", 'declare module "components-react";');

  const reactTableConfig = fs.readFileSync(
    "src/react-table-config.d.ts",
    "utf-8"
  );
  fs.writeFileSync("dist/react-table-config.d.ts", reactTableConfig, "utf-8");
} catch (err) {
  console.error("Error during postbuild ", err.message);
}
